AU = 1.49579151285e8;
mu_star = 1.32712440018e11; % [km3 / s2]
l_star = AU; % [km] one AU
m_star = 3000; % [kg] - max initial ship mass
a_star = mu_star / l_star ^ 2; % [km / s2]
t_star = sqrt(l_star ^ 3 / mu_star);
v_star = sqrt(mu_star/l_star);
year_to_sec = 86400.0 * 365.25;

mu = 1;
%%
ast_data = importdata('GTOC12_Asteroids_Data.txt');
offset = 2;
ast.a = ast_data.data(:, offset + 1);
ast.e = ast_data.data(:, offset + 2);
ast.inc = ast_data.data(:, offset + 3);
ast.Omega = ast_data.data(:, offset + 4);
ast.omega = ast_data.data(:, offset + 5);
ast.M0 = ast_data.data(:, offset + 6);
%%
%[text] ## Visualization
periods = 2 * pi * sqrt(ast.a .^ 3 / 1) * t_star / year_to_sec;
histogram(periods) %[output:0db03e4c]

h = histogram2(ast.a,ast.e,'DisplayStyle','tile','ShowEmptyBins','on'); %[output:152ef20e]
title("Eccentricity vs Semi-major Axis") %[output:152ef20e]
xlabel("Semi-major Axis") %[output:152ef20e]
ylabel("Eccentricity") %[output:152ef20e]

scatter(ast.a,ast.e); %[output:39a0d9c2]
title("Eccentricity vs Semi-major Axis") %[output:39a0d9c2]
xlabel("Semi-major Axis") %[output:39a0d9c2]
ylabel("Eccentricity") %[output:39a0d9c2]
%%
h = histogram2(ast.a,ast.inc,'DisplayStyle','tile','ShowEmptyBins','on'); %[output:6c04630d]
title("Inclination vs Semi-major Axis") %[output:6c04630d]
xlabel("Semi-major Axis") %[output:6c04630d]
ylabel("Inclination") %[output:6c04630d]
scatter(ast.a,ast.inc); %[output:55c98757]
title("Inclination vs Semi-major Axis") %[output:55c98757]
xlabel("Semi-major Axis") %[output:55c98757]
ylabel("Inclination") %[output:55c98757]
%%
scatter3(ast.a, ast.e, ast.inc) %[output:8c4b9d7a]
xlabel("Semimajor Axis") %[output:8c4b9d7a]
ylabel("Eccentricity") %[output:8c4b9d7a]
zlabel("Inclination") %[output:8c4b9d7a]
%%
ast_i = 1:60000;
ast_filter = (ast.a < 2.5) & (ast.a > 2) & (ast.e < 0.1) & (ast.inc < 5);
ast_filtered_i = ast_i(ast_filter);
%%
scatter3(ast.a, ast.e, ast.inc); hold on %[output:2f617022]
scatter3(ast.a(ast_filtered_i), ast.e(ast_filtered_i), ast.inc(ast_filtered_i)); hold off %[output:2f617022]
xlabel("Semimajor Axis") %[output:2f617022]
ylabel("Eccentricity") %[output:2f617022]
zlabel("Inclination") %[output:2f617022]
title("Asteroid Selection") %[output:2f617022]
n_ast = numel(ast_filtered_i) %[output:7ae7fd6e]
%%
% Earth orbit
a_earth = 1.49579e8 / AU;
e_earth = 1.65519e-2;
inc_earth = 4.64389e-3;
Omega_earth = 1.98956e2;
omega_earth = 2.62960e2;
M_earth0 = deg2rad(3.58040e2);
M_earth = @(t) sqrt(mu / a_earth^3) * t + M_earth0;
E_earth = @(t) mean_to_eccentric_anomaly(M_earth(t), e_earth);
nu_earth = @(t) rad2deg(eccentric_to_true_anomaly(E_earth(t), e_earth));

x_keplerian_earth = @(t) [a_earth e_earth inc_earth*pi/180 Omega_earth*pi/180 omega_earth*pi/180 M_earth(t)]';
x_cartesian_earth = @(t) keplerian_to_cartesian(x_keplerian_earth(t), [], mu);
%%
%[text] ## Get asteroid positions and velocities at waypoints
N_waypoints = 10;
ToF_waypoint = 0.5; % Years
t_waypoints = 2.6 + ToF_waypoint * (1:N_waypoints) %[output:84db7b04]
x_cart_earth_0 = x_cartesian_earth(t_waypoints(1));
x_cart_earth_f = x_cartesian_earth(t_waypoints(end));

ast_filtered = [];
ast_filtered.a = ast.a(ast_filtered_i);
ast_filtered.e = ast.e(ast_filtered_i);
ast_filtered.inc = deg2rad(ast.inc(ast_filtered_i));
ast_filtered.Omega = deg2rad(ast.Omega(ast_filtered_i));
ast_filtered.omega = deg2rad(ast.omega(ast_filtered_i));
ast_filtered.M0 = deg2rad(ast.M0(ast_filtered_i));
[x_kep_ast, x_cart_ast] = get_cartesian_states(ast_filtered, mu, t_waypoints);
%%
% Number of lambert solutions to compute (not matching what combinations is saying...)
(n_ast - 1) ^ 2 * (N_waypoints - 1) + n_ast %[output:1d3f283b]
%%
%[text] ## Create Lambert Inputs
% Earth -> Ast
x_1_EA = repmat(x_cart_earth_0, 1, n_ast);
x_2_EA = x_cart_ast(:, :, 1);

comb_i_full = combinations(1:n_ast, 1:n_ast);
comb_i = comb_i_full(comb_i_full.Var1 ~= comb_i_full.Var2, :);

x_1_AA = zeros([6, numel(comb_i.Var1), N_waypoints - 1]);
x_2_AA = zeros([6, numel(comb_i.Var1), N_waypoints - 1]);

% Ast1 -> Ast2
for i = 1 : (N_waypoints - 1)
    x_1_AA(:, :, i) = x_cart_ast(:, comb_i.Var1, i);
    x_2_AA(:, :, i) = x_cart_ast(:, comb_i.Var2, i + 1);
end

x_1_AA = reshape(x_1_AA, 6, []);
x_2_AA = reshape(x_2_AA, 6, []);
%%
Q_AA = size(x_1_AA, 2);
ToF_AA = ToF_waypoint * ones([Q_AA, 1]) * year_to_sec / t_star;
ToF_EA = t_waypoints(1) * ones([n_ast, 1]) * year_to_sec / t_star;

N_max = 1;
launch_assist = 6 / v_star;
%%
%[text] ## Compute Lambert
% Load lambert solver files
load_lambert(); %[output:718d643d] %[output:3350c495] %[output:818b24a4]
%%
% Earth -> Ast (possibly multi-rev)
[v1_best_EA, v2_best_EA, dV_best_EA, N_best_EA] = best_lambert_thruN(x_1_EA, x_2_EA, ToF_EA, N_max, launch_assist, 0);

% Ast -> Ast (zero rev for drop-off)
[v1_best_AA, v2_best_AA, dV_best_AA] = best_lambert_zeroN(x_1_AA, x_2_AA, ToF_AA, 0, 0);
%%
% Clean up lambert's mess
unload_lambert(); %[output:2cbefe6d]
%%
% Analyze results
m0 = 1; % Fraction of max mass (3000 kg)

dV_max_allowable_EA = simple_max_dV_surrogate(ToF_EA(1), m0) * v_star %[output:33ae64ae]
figure %[output:34fa6781]
histogram(dV_best_EA * v_star);  hold on %[output:34fa6781]
xline(dV_max_allowable_EA) %[output:34fa6781]
hold off %[output:34fa6781]
title(sprintf("Earth->Ast delta V Distribution for ToF of %g years", t_waypoints(1))); %[output:34fa6781]
xlabel("delta V [km / s]") %[output:34fa6781]
ylabel("Count") %[output:34fa6781]
dV_EA_avg = mean(dV_best_EA(dV_best_EA * v_star < dV_max_allowable_EA) * v_star) %[output:13a304bd]
m0_AA_avg = rockeq_dV_to_dm(dV_EA_avg, m0) %[output:5bdfcaee]
dV_max_allowable_AA = simple_max_dV_surrogate(ToF_AA(1), m0_AA_avg) * v_star %[output:2442e8d3]
figure %[output:6deae425]
histogram(dV_best_AA * v_star);  hold on %[output:6deae425]
xline(dV_max_allowable_AA) %[output:6deae425]
hold off %[output:6deae425]
title(sprintf("Ast->Ast delta V Distribution for ToF of %g years", ToF_waypoint)); %[output:6deae425]
xlabel("delta V [km / s]") %[output:6deae425]
ylabel("Count") %[output:6deae425]
%%
dV_AA_avg = mean(dV_best_AA(dV_best_AA * v_star < dV_max_allowable_AA) * v_star) %[output:1454455d]
mf_AA_avg = m0_AA_avg;
for i = 1 : numel(t_waypoints)*2 %[output:group:93558b87]
    mf_AA_avg = rockeq_dV_to_dm(dV_AA_avg, mf_AA_avg) %[output:3fa355d7] %[output:513ea6a8] %[output:29290ab4] %[output:3f99f59b] %[output:86f83cfa] %[output:08fbb97b] %[output:5f0c6727] %[output:22499d14] %[output:98638c3a] %[output:4ad1780a] %[output:712de265] %[output:3ff14c48] %[output:04023d95] %[output:92df6d6b] %[output:382040e9] %[output:5651a98a] %[output:51da2b9c] %[output:2244aa6b] %[output:80f31558] %[output:22fc8621]
end %[output:group:93558b87]
mf_avg = rockeq_dV_to_dm(dV_EA_avg, mf_AA_avg) %[output:0b5f9b04]
N_ship = 35; % Number of ships wanted
m_mined_avg = log(N_ship / 2) / 0.004 % [kg] %[output:71812268]
m_dry = 500; % [kg]
mf_min = (m_dry + m_mined_avg) / m_star %[output:06ee2817]
%%
sum(dV_best_EA * v_star < dV_max_allowable_EA) %[output:32133461]
ast_filtered_i(dV_best_EA * v_star < dV_max_allowable_EA) %[output:2d33249f]
find(dV_best_EA * v_star < dV_max_allowable_EA)' %[output:369d87af]
dV_best_EA(dV_best_EA * v_star < dV_max_allowable_EA)' %[output:7b1db9cc]
N_best_EA(dV_best_EA * v_star < dV_max_allowable_EA)' %[output:199c5821]
sum(dV_best_AA * v_star < dV_max_allowable_AA) %[output:141d430d]
%%
% Look at histograms for each 
m0_AA_avg_w = m0_AA_avg;
waypoint_ni = (numel(dV_best_AA) / (N_waypoints - 1));
total_a = 0;
dV_filter = zeros([numel(comb_i.Var1), N_waypoints - 1]);
for i = 1 : numel(t_waypoints) - 1 %[output:group:678df808]
    dV_max_allowable_AA_w = simple_max_dV_surrogate(ToF_AA(1), m0_AA_avg_w) * v_star %[output:6864bbd0] %[output:1537db86] %[output:5a021847] %[output:2cc4a91f] %[output:7731b8c2] %[output:525911be] %[output:4ce6eedb] %[output:59964382] %[output:9d74f6af]
    m0_AA_avg_w = rockeq_dV_to_dm(dV_max_allowable_AA_w, m0_AA_avg_w);
    figure %[output:7efd6f93] %[output:622c7904] %[output:462b3b8c] %[output:3ddc2d2f] %[output:02580a77] %[output:4b5ed063] %[output:6205a0cf] %[output:8f230d90] %[output:3df987c6]
    histogram(dV_best_AA((1 : waypoint_ni) + waypoint_ni * (i - 1)) * v_star - dV_max_allowable_AA_w) %[output:7efd6f93] %[output:622c7904] %[output:462b3b8c] %[output:3ddc2d2f] %[output:02580a77] %[output:4b5ed063] %[output:6205a0cf] %[output:8f230d90] %[output:3df987c6]
    total_a = total_a + sum(dV_best_AA((1 : waypoint_ni) + waypoint_ni * (i - 1)) * v_star - dV_max_allowable_AA_w < 0) %[output:1f13e8c1] %[output:6cfdbf1f] %[output:7371d33c] %[output:1a5a3012] %[output:75bd13be] %[output:8c6d5332] %[output:843f59c8] %[output:7bdc7056] %[output:0a75f811]
    dV_filter(:, i) = dV_best_AA((1 : waypoint_ni) + waypoint_ni * (i - 1)) * v_star - dV_max_allowable_AA_w < 0;
end %[output:group:678df808]
total_a %[output:03879b5f]
%%
% Look at the graph where edges greater than max are pruned 
edge_filter = comb_i_full.Var1 ~= comb_i_full.Var2;
edge_filter_i = find(edge_filter);

filtered_EA_i = find(dV_best_EA * v_star < dV_max_allowable_EA);

start_nodes = ones(size(filtered_EA_i));
end_nodes = filtered_EA_i + 1;
weights = dV_best_EA(filtered_EA_i);

start_layer_i = {};
end_layer_i = {};

start_layer_i{1} = start_nodes;
end_layer_i{1} = end_nodes;

for i = 1 : (N_waypoints - 1)
    i_filter = edge_filter_i(logical(dV_filter(:, i)));
    
    start_layer_i{i + 1} = comb_i_full.Var1(i_filter) + size(comb_i_full.Var1, 1) * (i - 1) + 1;
    start_nodes = [start_nodes; start_layer_i{i + 1}];
    end_layer_i{i + 1} = comb_i_full.Var2(i_filter) + size(comb_i_full.Var1, 1) * i + 1;
    end_nodes = [end_nodes; end_layer_i{i + 1}];
    weights = [weights; dV_best_AA(logical(dV_filter(:, i)))'];
end
%%
% Construct graph
G = digraph(start_nodes, end_nodes, weights);
G %[output:64b964b1]

%%
layer_valid_i{1} = 1;
next_valid = end_layer_i{1}(find(start_layer_i{1}));
G_pared = G;
for i = 2 : N_waypoints
    u_layer_start = unique(start_layer_i{i})';
    start_indeg = G.indegree(u_layer_start);
    start_filtered_i = u_layer_start(start_indeg ~= 0);
    
    u_layer_end = unique(end_layer_i{i - 1})';
    end_indeg = G.indegree(u_layer_end);
    end_filtered_i = u_layer_end(end_indeg ~= 0);

    layer_valid_i{i} = intersect(next_valid, intersect(start_filtered_i, end_filtered_i))';
    next_valid = end_layer_i{i}(find(start_layer_i{i}));


    u_layer_start = unique(start_layer_i{i})';
    start_indeg = G_pared.indegree(u_layer_start);
    start_filtered_i = u_layer_start(start_indeg == 0);
    
    u_layer_end = unique(end_layer_i{i - 1})';
    end_indeg = G_pared.indegree(u_layer_end);
    end_filtered_i = u_layer_end(end_indeg == 0);

    G_pared = G_pared.rmnode(start_filtered_i);
end
G_valid = G.subgraph([layer_valid_i{:}]);

%%
Gt = G.subgraph([1, layer_valid_i{2}]);
plot(Gt)
%%
i = 3;
start_layer_i{i} %[output:0b796637]
end_layer_i{i - 1} %[output:584ab419]
%%
Gt = G.subgraph(unique([layer_valid_i{1}'; layer_valid_i{2}'; start_layer_i{i}(G.outdegree(start_layer_i{i}) > 0); end_layer_i{i}(G.indegree(end_layer_i{i}) > 0)]));
plot(Gt)
%%
Gt = G.subgraph(unique([layer_valid_i{1}'; layer_valid_i{2}'; layer_valid_i{3}'; layer_valid_i{4}']));
plot(Gt)
%%
start_indeg = G_valid.indegree %[output:7d5461f4]
%%
% Cluster paths, select subsets for different ship groups
plot(G_valid)
%%
G_test = G.subgraph([1, 2, 3, 4, 5]) %[output:27b31b84]
plot(G_test)
